-- Boilers & Pressure plant, Fire: six combined questions split (BO01/BO06, BO04/BO07, BO05/BO08, FI02/FI07, FI04/FI08-09, FI05/FI10).
update public.hub_chk_points set q='Is the boiler''s yearly inspection certificate valid?', why='Running an uncertified boiler is illegal and very dangerous.', law='Boilers Act 2025', evidence='Boiler certificate', updated_at=now() where code='BO01';
update public.hub_chk_points set q='Is the PESO licence valid for solvent storage / gas cylinders?', why='Storing without a valid licence is an offence and voids insurance.', law='Petroleum Rules 2002; Gas Cylinder Rules 2016', evidence='PESO licence', updated_at=now() where code='BO04';
update public.hub_chk_points set q='Is the autoclave validated?', why='Needed for both GMP and safety.', law='Schedule M', evidence='Validation report', updated_at=now() where code='BO05';
update public.hub_chk_points set q='Are fire extinguishers refilled and tagged?', why='An empty extinguisher is useless on the day it is needed.', law='National Building Code; Fire NOC conditions', evidence='Refill tags', updated_at=now() where code='FI02';
update public.hub_chk_points set q='Are exits clear, with exit signs?', why='Blocked exits cause the deaths in a fire.', law='National Building Code Part 4', evidence='Photo checklist', updated_at=now() where code='FI04';
update public.hub_chk_points set q='Is wiring checked yearly?', why='Short circuit is the top cause of factory fires.', law='CEA Safety Regulations 2023', evidence='Electrical audit report', updated_at=now() where code='FI05';
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('BO06','Boilers & Pressure plant','Is the boiler registered?','Running an unregistered boiler is illegal and very dangerous.','Boilers Act 2025','boiler',array['labour']::text[],'H','Boiler registration certificate',9806,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('BO07','Boilers & Pressure plant','Is storage within the licensed quantity?','Excess storage voids insurance and risks an explosion case.','Petroleum Rules 2002; Gas Cylinder Rules 2016','peso',array['fire']::text[],'H','Stock register against licence',9807,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('BO08','Boilers & Pressure plant','Is the autoclave safety valve tested?','Needed for both GMP and safety.','Factories Act s.31','pressure',array['fda']::text[],'M','Valve test record',9808,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('FI07','Fire','Are hydrants and hose reels tested?','A dry hydrant is useless on the day it is needed.','National Building Code; Fire NOC conditions','',array['fire']::text[],'H','Hydrant test record',9907,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('FI08','Fire','Are emergency lights working?','Blocked or dark exits cause the deaths in a fire.','National Building Code Part 4','',array['fire']::text[],'H','Emergency light test record',9908,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('FI09','Fire','Is the fire alarm working?','An alarm that does not sound gives no warning.','National Building Code Part 4','',array['fire']::text[],'H','Alarm test record',9909,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('FI10','Fire','Is the solvent store fitted with flameproof fittings?','Short circuit is the top cause of factory fires.','CEA Safety Regulations 2023','mfg',array['fire']::text[],'M','Photo of fittings',9910,true,null) on conflict (code) do nothing;
