-- Existing answers (Velite Pharmaceuticals, Piyush Verma, 19 Nov 2026):
-- BO05 'NA' and FI02 'Yes' covered both halves, so they are copied to BO08 and FI07.
insert into public.hub_chk_answers(firm_id, code, answer, note, ref_no, proof_link, proof_path, proof_name, answered_by, answered_by_name, answered_at)
  select firm_id, 'BO08', answer, note, ref_no, proof_link, proof_path, proof_name, answered_by, answered_by_name, answered_at from public.hub_chk_answers where firm_id='VP' and code='BO05' on conflict do nothing;
insert into public.hub_chk_answers(firm_id, code, answer, note, ref_no, proof_link, proof_path, proof_name, answered_by, answered_by_name, answered_at)
